import {escapeHTML as esc} from './component-markings.mjs';
import {readProjects,writeProjects,projectFromSnapshot,validateProject} from './studio-projects.mjs';
export function mountStudio(api){
 document.body.classList.add('studioApp');const main=document.querySelector('main'),nav=document.querySelector('.academyNav');
 const home=document.createElement('section');home.id='homePage';home.hidden=true;main.prepend(home);
 const projects=document.createElement('section');projects.id='projectsPage';projects.hidden=true;main.append(projects);
 for(const [id,label]of [['home','Inicio'],['projects','Proyectos']]){const btn=document.createElement('button');btn.id='nav'+id;btn.textContent=label;id==='home'?nav.prepend(btn):nav.append(btn);btn.onclick=()=>api.show(id);}
 document.getElementById('navcourse').textContent='Aprender';document.getElementById('navlibrary').textContent='Explorar';document.getElementById('navlab').textContent='Laboratorio';document.getElementById('navscope').textContent='Señales';
 const brand=document.querySelector('.brand');brand.onclick=e=>{e.preventDefault();api.show('home');};
 const status=document.createElement('div');status.className='studioContext';status.innerHTML='<span>CIRCUITLAB / <b id="studioLocation">Inicio</b></span><span>LABORATORIO DE ELECTRÓNICA <b class="studioVersion">22</b></span>';main.before(status);
 const real=api.boards.filter(b=>!b.representative&&!b.educational).length;
 home.innerHTML=`<section class="studioHero"><div class="studioHeroCopy"><span class="studioEyebrow">TU LABORATORIO PERSONAL</span><h1>Comprende el circuito.<br><em>Domina el diagnóstico.</em></h1><p>De tu primer componente a una placa real. Aprende con un orden, explora las conexiones y comprueba tus hipótesis.</p><div class="studioHeroActions"><button id="studioContinue" class="academyPrimary">Continuar aprendiendo ↗</button><button id="studioExplore">Explorar placas</button></div></div><span class="heroCaption">Imagen conceptual del laboratorio</span></section><div class="studioMetrics"><span><b>${api.boards.length}</b> placas interactivas</span><span><b>${real}</b> diseños CAD reales</span><span><b>18</b> circuitos de referencia</span><span><b>3</b> instrumentos integrados</span></div><div class="studioSectionHead"><div><span class="studioEyebrow">ELIGE TU OBJETIVO</span><h2>Una herramienta para cada paso.</h2></div><p>Todos los recorridos llevan al mismo laboratorio.</p></div><div class="studioPaths"><button data-studio-path="course"><span class="pathNumber">01 / APRENDER</span><h3>Construye una base sólida.</h3><p>Resistencias, condensadores, bobinas, diodos y transistores. Una idea y una práctica cada vez.</p><span class="pathAction">Abrir mi recorrido <b>→</b></span></button><button data-studio-path="library"><span class="pathNumber">02 / EXPLORAR</span><h3>Lee la placa como un mapa.</h3><p>Localiza componentes, separa bloques y sigue las conexiones entre las dos caras.</p><span class="pathAction">Elegir una placa <b>→</b></span></button><button data-studio-path="diagnose"><span class="pathNumber">03 / DIAGNOSTICAR</span><h3>Convierte medidas en evidencias.</h3><p>Compara un circuito correcto con una avería preparada y registra tu razonamiento.</p><span class="pathAction">Preparar diagnóstico <b>→</b></span></button></div><section class="studioResume"><div><span class="studioEyebrow">TU TRABAJO, A MANO</span><h2>Retoma una investigación.</h2><p>Guarda placa, colores, puntos de medida y encuadre como un proyecto.</p><button id="studioProjects">Ver mis proyectos →</button></div><div id="studioRecent"></div></section>`;
 const $=id=>document.getElementById(id);$('studioContinue').onclick=()=>{api.show('course');$('planResume')?.click();};$('studioExplore').onclick=()=>api.show('library');$('studioProjects').onclick=()=>api.show('projects');home.querySelectorAll('[data-studio-path]').forEach(btn=>btn.onclick=()=>{if(btn.dataset.studioPath==='diagnose'){api.openDiagnosis();setMode('diagnose');}else api.show(btn.dataset.studioPath);});
 const tools=document.createElement('div');tools.className='studioWorkspaceBar';tools.innerHTML='<div role="group" aria-label="Espacio de trabajo"><button data-workspace="inspect" aria-pressed="true">Inspección</button><button data-workspace="diagnose" aria-pressed="false">Diagnóstico</button><button data-workspace="complete" aria-pressed="false">Todas las herramientas</button></div><div><button id="studioSave">Guardar proyecto</button><button id="studioOpenProjects">Mis proyectos ↗</button></div>';$('labPage').querySelector('.workspace').before(tools);
 function setMode(mode){$('labPage').dataset.workspace=mode;tools.querySelectorAll('[data-workspace]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.workspace===mode)));try{api.storage.setItem('circuitlab-workspace-v22',mode);}catch{}}
 document.addEventListener('circuitlab:workspace',e=>setMode(e.detail));tools.querySelectorAll('[data-workspace]').forEach(btn=>btn.onclick=()=>setMode(btn.dataset.workspace));$('studioOpenProjects').onclick=()=>api.show('projects');$('studioSave').onclick=()=>saveDialog();setMode('inspect');
 let items=readProjects(api.storage),activeId=null;
 function persist(next){try{writeProjects(api.storage,next);items=next;renderProjects();return true;}catch{showMessage('No se pudo guardar: el almacenamiento local está lleno o no está disponible. Exporta tu proyecto.');return false;}}
 function showMessage(text){$('projectStatus').textContent=text;}
 function download(project){const blob=new Blob([JSON.stringify(project,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='circuitlab-'+project.name.replace(/[^a-z0-9_-]/gi,'-')+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
 function open(id){const p=items.find(x=>x.id===id);if(!p)return;try{validateProject(p,api.boards.map(b=>b.id));api.restore(p.snapshot);activeId=id;api.show('lab');setMode('inspect');api.restoreCamera(p.snapshot.camera); }catch(e){showMessage(e.message);}}
 function saveDialog(){const d=document.createElement('dialog');d.className='studioProjectDialog';d.innerHTML=`<form><span class="studioEyebrow">GUARDAR INVESTIGACIÓN</span><h2>Un punto de partida para volver.</h2><label>Nombre del proyecto<input id="newProjectName" required maxlength="100" value="${esc(api.board().title)}"></label><p>Incluye el cuaderno de esta placa, las marcas y el encuadre. Se guarda en este navegador; exporta una copia para llevarla a otro dispositivo.</p><p class="projectDialogStatus" role="status"></p><div><button type="button" data-cancel>Cancelar</button><button type="button" data-export>Exportar archivo</button><button type="submit" class="academyPrimary">Guardar nuevo</button></div></form>`;document.body.append(d);d.querySelector('[data-cancel]').onclick=()=>d.close();const make=()=>projectFromSnapshot(d.querySelector('input').value||api.board().title,api.snapshot());d.querySelector('[data-export]').onclick=()=>download(make());d.querySelector('form').onsubmit=e=>{e.preventDefault();const p=make();if(persist([p,...items])){activeId=p.id;d.close();}else d.querySelector('.projectDialogStatus').textContent='No se pudo guardar. Usa Exportar archivo para conservarlo.';};d.addEventListener('close',()=>d.remove(),{once:true});d.showModal();}
 function renderProjects(){projects.innerHTML=`<div class="studioSectionHead"><div><span class="studioEyebrow">CUADERNO DE LABORATORIO</span><h1>Mis proyectos.</h1><p>Sesiones guardadas en este navegador. Exporta e importa para trasladarlas entre dispositivos.</p></div><div class="projectActions"><button id="projectNew">Guardar banco actual</button><label class="projectImport">Importar proyecto<input id="projectFile" type="file" accept=".json,application/json"></label></div></div><p id="projectStatus" role="status"></p><div class="studioProjectGrid">${items.length?items.map(p=>`<article class="studioProjectCard"><span class="studioEyebrow">${esc(api.boards.find(b=>b.id===p.snapshot.board)?.title||p.snapshot.board)}</span><h2>${esc(p.name)}</h2><p>${esc(new Date(p.updated).toLocaleString('es-ES'))}</p><p>${p.snapshot.notes?.points?.length||0} hitos · ${p.snapshot.notes?.readings?.length||0} mediciones</p><div><button data-open="${esc(p.id)}" class="academyPrimary">Retomar →</button><button data-export="${esc(p.id)}">Exportar</button><button data-delete="${esc(p.id)}">Eliminar</button></div></article>`).join(''):'<div class="studioEmpty"><span>◇</span><h2>Tu próxima investigación empieza aquí.</h2><p>Abre una placa, marca sus conexiones y pulsa Guardar proyecto.</p><button id="emptyExplore">Elegir una placa →</button></div>'}</div>`;
 $('projectNew').onclick=saveDialog;$('emptyExplore')?.addEventListener('click',()=>api.show('library'));projects.querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>open(b.dataset.open));projects.querySelectorAll('[data-export]').forEach(b=>b.onclick=()=>download(items.find(p=>p.id===b.dataset.export)));projects.querySelectorAll('[data-delete]').forEach(b=>b.onclick=()=>{const removed=items.find(p=>p.id===b.dataset.delete);if(persist(items.filter(p=>p.id!==removed.id))){showMessage('Proyecto eliminado.');const undo=document.createElement('button');undo.textContent='Deshacer';undo.onclick=()=>persist([removed,...items]);$('projectStatus').append(undo);}});
 $('projectFile').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>2e6)throw Error('El archivo supera 2 MB.');const p=validateProject(JSON.parse(await f.text()),api.boards.map(b=>b.id));p.id=projectFromSnapshot('',{}).id;if(persist([p,...items]))showMessage('Proyecto importado. Pulsa Retomar para abrirlo.');}catch(error){showMessage(error.message);}e.target.value='';};
 $('studioRecent').innerHTML=items.slice(0,3).map(p=>`<button data-recent="${esc(p.id)}"><span>${esc(p.name)}</span><small>${esc(api.boards.find(b=>b.id===p.snapshot.board)?.title||p.snapshot.board)}</small><b>↗</b></button>`).join('')||'<p class="studioNoProjects">Todavía no has guardado proyectos.<br>Empieza explorando una placa.</p>';$('studioRecent').querySelectorAll('[data-recent]').forEach(b=>b.onclick=()=>open(b.dataset.recent));}
 document.addEventListener('circuitlab:page',e=>{const names={home:'Inicio',course:'Aprender',library:'Explorar placas',lab:'Laboratorio',scope:'Señales e instrumentos',projects:'Proyectos'};$('studioLocation').textContent=names[e.detail]||'Laboratorio';try{api.storage.setItem('circuitlab-studio-page',e.detail);}catch{}});
 renderProjects();let last='home';try{last=api.storage.getItem('circuitlab-studio-page')||'home';}catch{}api.show(last);return {setMode,saveDialog};
}
